        if ((t & 1) == 0)
            stencil_step_parallel_rows(x0, x1, y0, y1, z0, z1, Nx, Ny, threads, coef, vsq, Aeven, Aodd);
        else
            stencil_step_parallel_rows(x0, x1, y0, y1, z0, z1, Nx, Ny, threads, coef, vsq, Aodd, Aeven);
