extern "C" void run(const void* input1, const void* input2, void* output, int n, int parameter, int threads) {
    const std::size_t s = static_cast<std::size_t>(n) * static_cast<std::size_t>(n) * static_cast<std::size_t>(n);
    const float* a = static_cast<const float*>(input1);
    float* c = static_cast<float*>(output);
    std::memcpy(c, a, s * sizeof(float));
    std::memset(c + s, 0, s * sizeof(float));
    const float co[4] = {.5f, -.25f, .125f, -.0625f};

    const int x0 = 4;
    const int x1 = n - 4;
    const int y0 = 4;
    const int y1 = n - 4;
    const int z0 = 4;
    const int z1 = n - 4;
    std::size_t active_cells = 0;
    if (x1 > x0 && y1 > y0 && z1 > z0) {
        active_cells = static_cast<std::size_t>(x1 - x0) * static_cast<std::size_t>(y1 - y0) *
                       static_cast<std::size_t>(z1 - z0);
