    const int Nxy = Nx * Ny;
    const int row_length = x1 - x0;
    constexpr std::uintptr_t alignment = 16;
    constexpr std::uintptr_t alignment_mask = alignment - 1;

    for (int z = z0; z < z1; ++z) {
        for (int y = y0; y < y1; ++y) {
